-- 테이블 삭제
DROP TABLE IF EXISTS stored_file;
DROP TABLE IF EXISTS review;
DROP TABLE IF EXISTS message;
DROP TABLE IF EXISTS chat_room;
DROP TABLE IF EXISTS payment;
DROP TABLE IF EXISTS reservation;
DROP TABLE IF EXISTS accommodation_amenity;
DROP TABLE IF EXISTS amenity;
DROP TABLE IF EXISTS reserved_date;
DROP TABLE IF EXISTS accommodation;
DROP TABLE IF EXISTS address;
DROP TABLE IF EXISTS payment_method;
DROP TABLE IF EXISTS user;


-- User 테이블
CREATE TABLE `user` (
  `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
  `email` VARCHAR(100) NOT NULL UNIQUE,
  `username` VARCHAR(50) NOT NULL,
  `login_id` VARCHAR(50) NOT NULL,
  `password` VARCHAR(255) NOT NULL,
  `role` VARCHAR(20) NOT NULL,
  `phone` VARCHAR(20) NOT NULL,
  `profile_url` VARCHAR(255),
  `created_at` DATETIME NOT NULL
);

-- Address 테이블
CREATE TABLE `address` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `city` VARCHAR(255),
    `district` VARCHAR(255),
    `street_address` VARCHAR(255),
    `detail_address` VARCHAR(255),
    `latitude` DOUBLE NOT NULL,
    `longitude` DOUBLE NOT NULL
);

-- Amenity 테이블
CREATE TABLE `amenity` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(50)
);

-- Accommodation 테이블
CREATE TABLE `accommodation` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(255) NOT NULL,
    `price_per_night` INT NOT NULL,
    `description` TEXT NOT NULL,
    `max_guests` INT NOT NULL,
    `bed_count` INT NOT NULL,
    `room_count` INT NOT NULL,
    `address_id` BIGINT UNIQUE,
    `created_at` DATETIME NOT NULL,
    `host_id` BIGINT NOT NULL,
    CONSTRAINT `fk_accommodation_address` FOREIGN KEY (`address_id`) REFERENCES `address`(`id`),
    CONSTRAINT `fk_accommodation_host` FOREIGN KEY (`host_id`) REFERENCES `user`(`id`)
);


-- AccommodationAmenity 테이블
CREATE TABLE `accommodation_amenity` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `accommodation_id` BIGINT NOT NULL,
    `amenity_id` BIGINT NOT NULL,
    CONSTRAINT `fk_accommodation_amenity_accommodation` FOREIGN KEY (`accommodation_id`) REFERENCES `accommodation`(`id`),
    CONSTRAINT `fk_accommodation_amenity_amenity` FOREIGN KEY (`amenity_id`) REFERENCES `amenity`(`id`)
);

-- StoredFile 테이블
CREATE TABLE `stored_file` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `file_url` VARCHAR(1000) NOT NULL,
    `target_type` VARCHAR(50) NOT NULL,
    `target_id` BIGINT NOT NULL,
    `file_order` INT NOT NULL
);

--
CREATE TABLE reservation (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    guest_id BIGINT NOT NULL,
    accommodation_id BIGINT NOT NULL,
    order_id VARCHAR(100) NOT NULL UNIQUE,
    check_in DATE NOT NULL,
    check_out DATE NOT NULL,
    guest_count INT NOT NULL,
    status VARCHAR(20) NOT NULL,
    service_fee BIGINT NOT NULL,
    total_price BIGINT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_reservation_guest FOREIGN KEY (guest_id) REFERENCES user(id),
    CONSTRAINT fk_reservation_accommodation FOREIGN KEY (accommodation_id) REFERENCES accommodation(id)
);


CREATE TABLE review (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    reservation_id BIGINT NOT NULL,
    rating DOUBLE NOT NULL,
    content TEXT NOT NULL,
    created_at DATETIME NOT NULL,
    CONSTRAINT fk_review_reservation
        FOREIGN KEY (reservation_id) REFERENCES reservation(id)
);

CREATE TABLE reserved_date (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    accommodation_id BIGINT NOT NULL,
    reserved_date DATE NOT NULL,
    CONSTRAINT uq_reserved UNIQUE (accommodation_id, reserved_date),
    FOREIGN KEY (accommodation_id) REFERENCES accommodation(id)
);

CREATE TABLE chat_room (
                           id BIGINT AUTO_INCREMENT PRIMARY KEY,
                           host_id BIGINT NOT NULL,
                           guest_id BIGINT NOT NULL,
                           reservation_id BIGINT UNIQUE, -- OneToOne 매핑
                           created_at DATETIME NOT NULL,
                           last_message VARCHAR(500),
                           last_message_at DATETIME,

                           FOREIGN KEY (host_id) REFERENCES user(id),
                           FOREIGN KEY (guest_id) REFERENCES user(id),
                           FOREIGN KEY (reservation_id) REFERENCES reservation(id)
);

CREATE TABLE message (
                         id BIGINT AUTO_INCREMENT PRIMARY KEY,
                         chat_room_id BIGINT NOT NULL,
                         sender_id BIGINT NOT NULL,
                         content TEXT NOT NULL,
                         sent_at DATETIME NOT NULL,

                         FOREIGN KEY (chat_room_id) REFERENCES chat_room(id),
                         FOREIGN KEY (sender_id) REFERENCES user(id)
);


