('전통 하우스', 94979, '쇼핑, 먹거리, 역사 문화 체험까지 모두 즐길 수 있습니다. 특히 강남, 홍대, 명동 등 다양한 지역에서 색다른 경험을 할 수 있으며, 한강을 따라 산책하거나 북촌한옥마을과 경복궁에서 전통을 느껴보세요.. 서울은 대한민국의 수도로서 현대적 고층 빌딩과 고궁이 공존하는 도시입니다.', 9, 1, 2, 1, '2025-01-01 12:01:00', 10),
