INSERT INTO review (reservation_id, rating, content, created_at) VALUES
(3, 4.5, '숙소가 매우 깨끗하고 호스트가 친절했습니다.', '2025-06-20 14:23:01'),
(7, 3.0, '위치는 좋았지만 방음이 조금 아쉬웠어요.', '2025-06-18 11:45:10'),
(15, 5.0, '정말 편안한 숙박이었고 다음에도 이용할게요!', '2025-06-22 09:12:45'),
(2, 4.0, '가격 대비 만족스러운 숙소였습니다.', '2025-06-21 18:00:00'),
(11, 2.5, '청결 상태가 기대에 미치지 못했어요.', '2025-06-15 16:30:22'),
(20, 4.5, '주변에 맛집도 많고 여행하기 좋았습니다.', '2025-06-19 20:11:03'),
(6, 5.0, '침대가 매우 편안해서 푹 잘 수 있었어요.', '2025-06-21 13:55:59'),
(25, 3.5, '전체적으로 괜찮았지만 화장실이 작았어요.', '2025-06-17 10:25:14'),
(9, 4.0, '깔끔한 인테리어가 마음에 들었습니다.', '2025-06-20 22:40:05'),
(14, 1.5, '호스트와의 소통이 원활하지 않았습니다.', '2025-06-16 08:15:50'),
(27, 4.0, '재방문 의사 있습니다. 주변 환경이 좋네요.', '2025-06-23 12:00:00'),
(19, 5.0, '아이와 함께 지내기 좋은 공간입니다.', '2025-06-22 14:45:30'),
(13, 3.0, '가격 대비 시설이 다소 낡았습니다.', '2025-06-18 19:20:11'),
(1, 4.5, '친절한 호스트 덕분에 즐거운 여행이었어요.', '2025-06-20 16:30:00'),
(5, 2.0, '예약 과정에 문제가 있었습니다.', '2025-06-17 21:00:00'),
(22, 4.0, '조용한 동네에 위치해 숙면하기 좋았어요.', '2025-06-21 07:35:22'),
(8, 3.5, '주차 공간이 협소해서 불편했습니다.', '2025-06-19 15:00:45'),
(28, 5.0, '아름다운 전망과 넓은 공간이 인상적이었어요.', '2025-06-23 10:10:10'),
(4, 4.0, '가성비 좋은 숙소라 추천합니다.', '2025-06-20 09:00:00'),
(10, 3.0, '냉난방 시설이 고장 나서 조금 힘들었어요.', '2025-06-18 23:15:00');

